      '<section class="box"><header class="sh"><h2>' + ic('users') + IS.T('آخر الملتحقين', 'Latest enrolments') + '</h2><a class="more" href="#studio-students">' + esc(A('الكل', 'All')) + '</a></header>' + (mo.es.length ? '<div class="list">' + mo.es.slice(-6).reverse().map(function (e) { var c = cs.filter(function (x) { return x.id === e.course_id; })[0] || {}; return '<div class="li">' + IS.av({ name: e.payer }, 'sm') + '<span><b>' + esc(e.payer || '') + '</b><small>' + esc(c.title || '') + '</small></span><em>' + esc(IS.ago(e.decided_at || e.created_at)) + '</em></div>'; }).join('') + '</div>' : '<p class="mut">' + esc(A('لا يوجد ملتحقون بعد.', 'No enrolments yet.')) + '</p>') + '</section></div>' +
      '<aside class="aside"><section class="box"><h2>' + ic('sparkle') + IS.T('إجراءات سريعة', 'Quick actions') + '</h2><div class="list">' + [['studio-course/new', 'plus', A('إنشاء كورس', 'Create a course')], ['studio-guide', 'book', A('دليل المحاضر ومعايير القبول', 'Lecturer guide and acceptance terms')], ['studio-page', 'user', A('تصميم صفحتي', 'Design my page')], ['studio-events', 'cal', A('إعلان فعالية', 'Announce an event')], ['studio-qa', 'chat', A('الرد على الأسئلة', 'Answer questions')], ['studio-money', 'wallet', A('طلب تحويل الأرباح', 'Request a payout')]].map(function (q) { return '<a class="li" href="#' + q[0] + '">' + ic(q[1]) + '<span><b>' + esc(q[2]) + '</b></span>' + ic('chev', 'fl') + '</a>'; }).join('') + '</div></section>' +
      '<section class="box"><h2>' + ic('cal') + IS.T('فعالياتي القادمة', 'My upcoming events') + '</h2>' + (r[3].filter(function (e) { return new Date(e.starts) > new Date(); }).map(function (e) { return '<a class="li" href="#event/' + e.id + '">' + ic('cal') + '<span><b>' + esc(e.title) + '</b><small>' + esc(IS.date(e.starts, { weekday: 'short', day: 'numeric', month: 'short', hour: '2-digit', minute: '2-digit' })) + '</small></span></a>'; }).join('') || '<p class="mut">' + esc(A('لا توجد فعاليات قادمة.', 'No upcoming events.')) + '</p>') + '</section></aside></div>';
